from __future__ import annotations

from pathlib import Path


def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


root = Path(__file__).resolve().parents[1]
provider_path = root / "providers" / "eodhd.py"
text = provider_path.read_text(encoding="utf-8")

text = replace_once(
    text,
    '''_LIVE_DATASET_QUERY_GRACE = timedelta(minutes=5)\n\n\nclass EODHDProviderError(ProviderDatasetError):\n    """Raised when EODHD cannot return a valid governed response."""\n\n\n@dataclass(frozen=True, slots=True)\nclass EODHDRetrievalPolicy:''',
    '''_LIVE_DATASET_QUERY_GRACE = timedelta(minutes=5)\n_ACTIVE_ONLY_SYMBOL_DIRECTORIES = frozenset({"CC", "FOREX", "BOND", "GBOND"})\n_DIRECTORY_REQUEST_TIMEOUT_SECONDS = 90\n_DEFAULT_DIRECTORY_CACHE_MAX_AGE_HOURS = 72.0\n\n\nclass EODHDProviderError(ProviderDatasetError):\n    """Raised when EODHD cannot return a valid governed response."""\n\n\nclass EODHDRetrievalFailure(EODHDProviderError):\n    """Credential-safe classified retrieval failure used by resilience controls."""\n\n    def __init__(\n        self,\n        *,\n        resource: str,\n        category: str,\n        retryable: bool,\n        status_code: int | None = None,\n    ) -> None:\n        self.resource = resource\n        self.category = category\n        self.retryable = retryable\n        self.status_code = status_code\n        detail = (\n            f"HTTP {status_code}"\n            if status_code is not None\n            else category.replace("_", " ")\n        )\n        retry_state = "retryable" if retryable else "non-retryable"\n        super().__init__(\n            f"unable to retrieve {resource} from EODHD "\n            f"({detail}; {retry_state})"\n        )\n\n\n@dataclass(frozen=True, slots=True)\nclass EODHDRetrievalPolicy:''',
    label="retrieval failure class",
)

text = replace_once(
    text,
    '''        sleeper: Callable[[float], None] | None = None,\n        retrieval_policy: EODHDRetrievalPolicy | None = None,\n    ) -> None:''',
    '''        sleeper: Callable[[float], None] | None = None,\n        retrieval_policy: EODHDRetrievalPolicy | None = None,\n        directory_cache_dir: str | Path | None = None,\n        directory_cache_max_age: timedelta | None = None,\n    ) -> None:''',
    label="provider constructor signature",
)

text = replace_once(
    text,
    '''        self._sleeper = sleeper or time_module.sleep\n        self._policy = retrieval_policy or EODHDRetrievalPolicy()\n''',
    '''        self._sleeper = sleeper or time_module.sleep\n        self._policy = retrieval_policy or EODHDRetrievalPolicy()\n        configured_cache_dir = (\n            directory_cache_dir\n            or os.getenv("CAPITAL_INTELLIGENCE_EODHD_DIRECTORY_CACHE_DIR")\n        )\n        if configured_cache_dir is None:\n            configured_cache_dir = (\n                Path(os.getenv("CAPITAL_INTELLIGENCE_DATA_DIR", "database"))\n                / "provider_cache"\n                / "eodhd_symbol_directories"\n            )\n        self._directory_cache_dir = Path(configured_cache_dir).expanduser()\n        if directory_cache_max_age is None:\n            try:\n                cache_hours = float(\n                    os.getenv(\n                        "CAPITAL_INTELLIGENCE_EODHD_DIRECTORY_CACHE_MAX_AGE_HOURS",\n                        str(_DEFAULT_DIRECTORY_CACHE_MAX_AGE_HOURS),\n                    )\n                )\n            except ValueError as error:\n                raise ValueError(\n                    "EODHD directory cache maximum age must be numeric"\n                ) from error\n            directory_cache_max_age = timedelta(hours=cache_hours)\n        if directory_cache_max_age <= timedelta(0):\n            raise ValueError("directory_cache_max_age must be positive")\n        self._directory_cache_max_age = directory_cache_max_age\n''',
    label="provider constructor cache state",
)

text = replace_once(
    text,
    '''        snapshot_query = query\n        live_retrieval_limitations: tuple[str, ...] = ()\n''',
    '''        snapshot_query = query\n        live_retrieval_limitations: tuple[str, ...] = ()\n        quality_state = DataQualityState.LIVE\n        observed_at_override: datetime | None = None\n        available_at_override: datetime | None = None\n''',
    label="snapshot quality state",
)

old_directory = '''        elif dataset_type is ProviderDatasetType.SYMBOL_DIRECTORY:\n            payload = {\n                "active": self._request(\n                    f"/exchange-symbol-list/{query.provider_symbol}",\n                    params={"delisted": 0},\n                    resource=f"active symbol directory {query.provider_symbol}",\n                ),\n                "delisted": self._request(\n                    f"/exchange-symbol-list/{query.provider_symbol}",\n                    params={"delisted": 1},\n                    resource=f"delisted symbol directory {query.provider_symbol}",\n                ),\n            }\n            limitations = (\n                "current and delisted symbol lists do not establish complete historical identifier lineage",\n                "venue and symbol changes require a separately certified security-master history",\n            )\n'''
new_directory = '''        elif dataset_type is ProviderDatasetType.SYMBOL_DIRECTORY:\n            (\n                active_directory,\n                quality_state,\n                cached_at,\n                directory_limitations,\n            ) = self._active_symbol_directory(\n                query.provider_symbol,\n                retrieved_at=retrieved_at,\n            )\n            if cached_at is not None:\n                observed_at_override = cached_at\n                available_at_override = cached_at\n            delisted_directory: list[Any] = []\n            if query.provider_symbol not in _ACTIVE_ONLY_SYMBOL_DIRECTORIES:\n                raw_delisted = self._request(\n                    f"/exchange-symbol-list/{query.provider_symbol}",\n                    params={"delisted": 1},\n                    resource=f"delisted symbol directory {query.provider_symbol}",\n                    timeout=max(self.timeout, _DIRECTORY_REQUEST_TIMEOUT_SECONDS),\n                )\n                if not isinstance(raw_delisted, list):\n                    raise EODHDRetrievalFailure(\n                        resource=(\n                            f"delisted symbol directory {query.provider_symbol}"\n                        ),\n                        category="invalid_payload_shape",\n                        retryable=True,\n                    )\n                delisted_directory = raw_delisted\n            else:\n                directory_limitations = (\n                    *directory_limitations,\n                    "provider virtual-market directory is active-only; a delisted request is not applicable",\n                )\n            payload = {\n                "active": active_directory,\n                "delisted": delisted_directory,\n            }\n            limitations = (\n                "current and delisted symbol lists do not establish complete historical identifier lineage",\n                "venue and symbol changes require a separately certified security-master history",\n                *directory_limitations,\n            )\n'''
text = replace_once(
    text,
    old_directory,
    new_directory,
    label="symbol directory retrieval",
)

text = replace_once(
    text,
    '''        observed_at = self._payload_observed_at(payload, fallback=retrieved_at)\n        if observed_at > retrieved_at:\n            observed_at = retrieved_at\n        return ProviderDatasetSnapshot(\n            query=snapshot_query,\n            provider=self.name,\n            source_version=EODHD_SOURCE_VERSION,\n            observed_at=observed_at,\n            available_at=retrieved_at,\n            retrieved_at=retrieved_at,\n            quality_state=DataQualityState.LIVE,\n''',
    '''        available_at = available_at_override or retrieved_at\n        observed_at = observed_at_override or self._payload_observed_at(\n            payload,\n            fallback=available_at,\n        )\n        if observed_at > available_at:\n            observed_at = available_at\n        return ProviderDatasetSnapshot(\n            query=snapshot_query,\n            provider=self.name,\n            source_version=EODHD_SOURCE_VERSION,\n            observed_at=observed_at,\n            available_at=available_at,\n            retrieved_at=retrieved_at,\n            quality_state=quality_state,\n''',
    label="snapshot cached lineage",
)

method_anchor = '''    def _fetch_bars(\n'''
if text.count(method_anchor) != 1:
    raise RuntimeError("active directory method anchor is not unique")
active_methods = '''    def _active_symbol_directory(\n        self,\n        provider_symbol: str,\n        *,\n        retrieved_at: datetime,\n    ) -> tuple[list[Any], DataQualityState, datetime | None, tuple[str, ...]]:\n        resource = f"active symbol directory {provider_symbol}"\n        try:\n            payload = self._request(\n                f"/exchange-symbol-list/{provider_symbol}",\n                resource=resource,\n                timeout=max(self.timeout, _DIRECTORY_REQUEST_TIMEOUT_SECONDS),\n            )\n            if not isinstance(payload, list):\n                raise EODHDRetrievalFailure(\n                    resource=resource,\n                    category="invalid_payload_shape",\n                    retryable=True,\n                )\n            cache_written = self._write_directory_cache(\n                provider_symbol,\n                payload,\n                retrieved_at=retrieved_at,\n            )\n            limitations = (\n                ()\n                if cache_written\n                else (\n                    "live directory was retrieved but the resilience cache could not be refreshed",\n                )\n            )\n            return payload, DataQualityState.LIVE, None, limitations\n        except EODHDRetrievalFailure as error:\n            if not error.retryable:\n                raise\n            cached = self._load_directory_cache(\n                provider_symbol,\n                evaluated_at=retrieved_at,\n            )\n            if cached is None:\n                raise\n            cached_at, payload = cached\n            age = retrieved_at - cached_at\n            return (\n                payload,\n                DataQualityState.CACHED,\n                cached_at,\n                (\n                    f"live {resource} failed; using the last successful directory cached "\n                    f"{age.total_seconds() / 3600.0:.1f} hours earlier",\n                    str(error),\n                    "cached directory evidence cannot independently authorize a no-superior-opportunity conclusion",\n                ),\n            )\n\n    def _directory_cache_path(self, provider_symbol: str) -> Path:\n        safe_symbol = "".join(\n            character\n            for character in provider_symbol.strip().upper()\n            if character.isalnum() or character in {"-", "_"}\n        )\n        if not safe_symbol:\n            raise ValueError("provider_symbol cannot be empty")\n        return self._directory_cache_dir / f"{safe_symbol}.json"\n\n    def _write_directory_cache(\n        self,\n        provider_symbol: str,\n        payload: list[Any],\n        *,\n        retrieved_at: datetime,\n    ) -> bool:\n        path = self._directory_cache_path(provider_symbol)\n        material = {\n            "schema_version": "eodhd-symbol-directory-cache.v1",\n            "provider_symbol": provider_symbol.strip().upper(),\n            "retrieved_at": retrieved_at.isoformat(),\n            "payload": payload,\n        }\n        temporary = path.with_suffix(f".tmp-{os.getpid()}")\n        try:\n            path.parent.mkdir(parents=True, exist_ok=True)\n            temporary.write_text(\n                json.dumps(\n                    material,\n                    sort_keys=True,\n                    separators=(",", ":"),\n                    allow_nan=False,\n                ),\n                encoding="utf-8",\n            )\n            temporary.replace(path)\n        except (OSError, TypeError, ValueError):\n            try:\n                temporary.unlink(missing_ok=True)\n            except OSError:\n                pass\n            return False\n        return True\n\n    def _load_directory_cache(\n        self,\n        provider_symbol: str,\n        *,\n        evaluated_at: datetime,\n    ) -> tuple[datetime, list[Any]] | None:\n        path = self._directory_cache_path(provider_symbol)\n        try:\n            material = json.loads(path.read_text(encoding="utf-8"))\n            if not isinstance(material, dict):\n                return None\n            if material.get("schema_version") != "eodhd-symbol-directory-cache.v1":\n                return None\n            if str(material.get("provider_symbol", "")).strip().upper() != (\n                provider_symbol.strip().upper()\n            ):\n                return None\n            cached_at = datetime.fromisoformat(\n                str(material["retrieved_at"]).replace("Z", "+00:00")\n            )\n            if cached_at.tzinfo is None or cached_at.utcoffset() is None:\n                return None\n            age = evaluated_at - cached_at\n            if age < timedelta(0) or age > self._directory_cache_max_age:\n                return None\n            payload = material.get("payload")\n            if not isinstance(payload, list) or not all(\n                isinstance(item, dict) for item in payload\n            ):\n                return None\n        except (OSError, KeyError, TypeError, ValueError, json.JSONDecodeError):\n            return None\n        return cached_at, payload\n\n'''
text = text.replace(method_anchor, active_methods + method_anchor, 1)

request_start = text.index("    def _request(\n")
request_end = text.index("\n    def _now(", request_start)
new_request = '''    def _request(\n        self,\n        path: str,\n        *,\n        params: Mapping[str, object] | None = None,\n        resource: str,\n        timeout: int | None = None,\n    ) -> Any:\n        if not self.api_token:\n            raise EODHDProviderError(\n                "CAPITAL_INTELLIGENCE_EODHD_API_TOKEN is not configured"\n            )\n        parameters = dict(params or {})\n        parameters["api_token"] = self.api_token\n        parameters.setdefault("fmt", "json")\n        url = EODHD_API_BASE + path\n        last_failure: EODHDRetrievalFailure | None = None\n        last_cause: Exception | None = None\n        for attempt in range(1, self._policy.max_attempts + 1):\n            failure: EODHDRetrievalFailure | None = None\n            cause: Exception | None = None\n            try:\n                response = self._http_get(\n                    url,\n                    params=parameters,\n                    timeout=(self.timeout if timeout is None else timeout),\n                )\n            except requests.Timeout as error:\n                cause = error\n                failure = EODHDRetrievalFailure(\n                    resource=resource,\n                    category="timeout",\n                    retryable=True,\n                )\n            except requests.ConnectionError as error:\n                cause = error\n                failure = EODHDRetrievalFailure(\n                    resource=resource,\n                    category="connection_error",\n                    retryable=True,\n                )\n            except requests.RequestException as error:\n                cause = error\n                failure = EODHDRetrievalFailure(\n                    resource=resource,\n                    category="network_error",\n                    retryable=True,\n                )\n            else:\n                try:\n                    status_code = int(getattr(response, "status_code", 0))\n                except (TypeError, ValueError) as error:\n                    cause = error\n                    failure = EODHDRetrievalFailure(\n                        resource=resource,\n                        category="invalid_http_response",\n                        retryable=True,\n                    )\n                else:\n                    if status_code in self._policy.retry_statuses:\n                        failure = EODHDRetrievalFailure(\n                            resource=resource,\n                            category="temporary_http_status",\n                            retryable=True,\n                            status_code=status_code,\n                        )\n                    elif status_code in {401, 403}:\n                        failure = EODHDRetrievalFailure(\n                            resource=resource,\n                            category="authentication_or_entitlement",\n                            retryable=False,\n                            status_code=status_code,\n                        )\n                    elif status_code < 200 or status_code >= 300:\n                        failure = EODHDRetrievalFailure(\n                            resource=resource,\n                            category="http_status",\n                            retryable=False,\n                            status_code=status_code,\n                        )\n                    else:\n                        try:\n                            payload = response.json()\n                        except (TypeError, ValueError) as error:\n                            cause = error\n                            failure = EODHDRetrievalFailure(\n                                resource=resource,\n                                category="invalid_json",\n                                retryable=True,\n                            )\n                        else:\n                            if isinstance(payload, dict) and payload.get("error"):\n                                provider_error = str(payload.get("error", "")).lower()\n                                retryable = any(\n                                    marker in provider_error\n                                    for marker in (\n                                        "rate",\n                                        "limit",\n                                        "tempor",\n                                        "timeout",\n                                        "unavailable",\n                                    )\n                                )\n                                failure = EODHDRetrievalFailure(\n                                    resource=resource,\n                                    category="provider_rejection",\n                                    retryable=retryable,\n                                )\n                            elif not isinstance(payload, (dict, list)):\n                                failure = EODHDRetrievalFailure(\n                                    resource=resource,\n                                    category="invalid_payload_shape",\n                                    retryable=True,\n                                )\n                            else:\n                                return payload\n            if failure is None:  # pragma: no cover - defensive completeness\n                failure = EODHDRetrievalFailure(\n                    resource=resource,\n                    category="unknown_retrieval_failure",\n                    retryable=True,\n                )\n            last_failure = failure\n            last_cause = cause\n            if not failure.retryable or attempt >= self._policy.max_attempts:\n                break\n            self._sleeper(\n                float(self._policy.backoff_seconds) * (2 ** (attempt - 1))\n            )\n        assert last_failure is not None\n        if last_cause is not None:\n            raise last_failure from last_cause\n        raise last_failure\n'''
text = text[:request_start] + new_request + text[request_end:]

text = replace_once(
    text,
    '''    "EODHDProviderError",\n    "EODHDRetrievalPolicy",\n''',
    '''    "EODHDProviderError",\n    "EODHDRetrievalFailure",\n    "EODHDRetrievalPolicy",\n''',
    label="public retrieval failure export",
)

provider_path.write_text(text, encoding="utf-8")

test_path = root / "tests" / "test_eodhd_directory_resilience.py"
test_path.write_text(
    '''from __future__ import annotations\n\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\n\nimport pytest\n\nfrom data.observation import DataQualityState\nfrom data.provider_dataset import ProviderDatasetQuery, ProviderDatasetType\nfrom providers.eodhd import (\n    EODHDBindingRegistry,\n    EODHDProvider,\n    EODHDProviderError,\n    EODHDRetrievalPolicy,\n)\n\n\nNOW = datetime(2026, 8, 2, 15, 45, tzinfo=timezone.utc)\n\n\nclass Response:\n    def __init__(self, payload, status_code: int = 200) -> None:\n        self.payload = payload\n        self.status_code = status_code\n\n    def json(self):\n        return self.payload\n\n\ndef provider(\n    responses,\n    *,\n    cache_dir: Path,\n    now: datetime = NOW,\n    calls: list[tuple[str, dict[str, object], int]] | None = None,\n    cache_age: timedelta = timedelta(hours=72),\n) -> EODHDProvider:\n    queue = list(responses)\n\n    def get(url, *, params, timeout):\n        if calls is not None:\n            calls.append((url, dict(params), timeout))\n        return queue.pop(0)\n\n    return EODHDProvider(\n        api_token="secret-token",\n        bindings=EODHDBindingRegistry(()),\n        http_get=get,\n        clock=lambda: now,\n        sleeper=lambda _: None,\n        retrieval_policy=EODHDRetrievalPolicy(max_attempts=1),\n        directory_cache_dir=cache_dir,\n        directory_cache_max_age=cache_age,\n    )\n\n\ndef query(as_of: datetime = NOW) -> ProviderDatasetQuery:\n    return ProviderDatasetQuery(\n        dataset_type=ProviderDatasetType.SYMBOL_DIRECTORY,\n        provider_symbol="CC",\n        as_of=as_of,\n    )\n\n\ndef live_payload():\n    return [\n        {\n            "Code": "BTC-USD",\n            "Name": "Bitcoin / US Dollar",\n            "Exchange": "CC",\n            "Currency": "USD",\n            "Type": "Currency",\n        }\n    ]\n\n\ndef test_cc_directory_uses_active_endpoint_without_delisted_parameter(\n    tmp_path: Path,\n) -> None:\n    calls: list[tuple[str, dict[str, object], int]] = []\n    snapshot = provider(\n        [Response(live_payload())],\n        cache_dir=tmp_path,\n        calls=calls,\n    ).fetch_dataset(query())\n\n    assert snapshot.quality_state is DataQualityState.LIVE\n    assert snapshot.payload["active"] == live_payload()\n    assert snapshot.payload["delisted"] == []\n    assert len(calls) == 1\n    assert calls[0][0].endswith("/exchange-symbol-list/CC")\n    assert "delisted" not in calls[0][1]\n    assert calls[0][2] == 90\n\n\ndef test_transient_directory_failure_uses_recent_successful_cache(\n    tmp_path: Path,\n) -> None:\n    provider([Response(live_payload())], cache_dir=tmp_path).fetch_dataset(query())\n    later = NOW + timedelta(hours=2)\n    snapshot = provider(\n        [Response({}, 503)],\n        cache_dir=tmp_path,\n        now=later,\n    ).fetch_dataset(query(later))\n\n    assert snapshot.quality_state is DataQualityState.CACHED\n    assert snapshot.observed_at == NOW\n    assert snapshot.payload["active"] == live_payload()\n    assert any("last successful directory" in item for item in snapshot.limitations)\n    assert any("HTTP 503" in item for item in snapshot.limitations)\n\n\ndef test_expired_directory_cache_remains_fail_closed(tmp_path: Path) -> None:\n    provider([Response(live_payload())], cache_dir=tmp_path).fetch_dataset(query())\n    later = NOW + timedelta(hours=73)\n\n    with pytest.raises(EODHDProviderError, match="HTTP 503"):\n        provider(\n            [Response({}, 503)],\n            cache_dir=tmp_path,\n            now=later,\n        ).fetch_dataset(query(later))\n\n\ndef test_authentication_failure_never_uses_cache(tmp_path: Path) -> None:\n    provider([Response(live_payload())], cache_dir=tmp_path).fetch_dataset(query())\n    later = NOW + timedelta(hours=1)\n\n    with pytest.raises(EODHDProviderError, match="HTTP 403.*non-retryable"):\n        provider(\n            [Response({}, 403)],\n            cache_dir=tmp_path,\n            now=later,\n        ).fetch_dataset(query(later))\n\n\ndef test_failure_diagnostic_is_precise_and_secret_free(tmp_path: Path) -> None:\n    with pytest.raises(EODHDProviderError) as captured:\n        provider(\n            [Response({}, 429)],\n            cache_dir=tmp_path,\n        ).fetch_dataset(query())\n\n    detail = str(captured.value)\n    assert "HTTP 429" in detail\n    assert "retryable" in detail\n    assert "secret-token" not in detail\n''',
    encoding="utf-8",
)
